import{_ as a}from"./chunks/EP.02-amis-advanced.CBSmyQse.js";import{_ as o,o as d,c as t,a2 as r}from"./chunks/framework.CnJ-JtFX.js";const f=JSON.parse('{"title":"EP.02 接口一改，页面不崩","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.02-amis-advanced.md","filePath":"comics/EP.02-amis-advanced.md","lastUpdated":1792683644000}'),s={name:"comics/EP.02-amis-advanced.md"};function c(i,e,l,n,p,h){return d(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ep-02-接口一改-页面不崩" tabindex="-1">EP.02 接口一改，页面不崩 <a class="header-anchor" href="#ep-02-接口一改-页面不崩" aria-label="Permalink to &quot;EP.02 接口一改，页面不崩&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/02-amis-advanced">guide/02-amis-advanced</a></p></blockquote><p><img src="'+a+'" alt="EP.02 漫画"></p><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：后端把 <code>customer</code> 改成 <code>customer_name</code>，列表从 <code>items</code> 改成 <code>list</code>，状态从字符串改成数字；三十个页面跟着改三十次适配。</li><li><strong>揭秘</strong>：码叔把协议拆成三层——<code>fetcher</code> 管 HTTP，<code>adaptor</code> 管业务协议，<code>Renderer</code> 管展示协议。</li><li><strong>实证</strong>：像素酱演示 <code>visibleOn</code> / <code>disabledOn</code> 做联动，<code>Renderer</code> 注册 <code>order-status</code> 徽章，表格列直接用 <code>type</code> 命中组件。</li><li><strong>结案</strong>：接口再改也只改 adaptor，页面结构不动；最常见的坑是 fetcher 直接返回业务数据，导致 adaptor 收到 <code>undefined</code>。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-没有适配层-接口就是页面的一部分" tabindex="-1">第一格：没有适配层，接口就是页面的一部分 <a class="header-anchor" href="#第一格-没有适配层-接口就是页面的一部分" aria-label="Permalink to &quot;第一格：没有适配层，接口就是页面的一部分&quot;">​</a></h3><p>接口字段一旦被写进 Schema，后端每次改名都会传导到页面。更麻烦的是，不同页面可能对同一份响应做不同转换，最后没人说得清「状态 2」代表已付款还是已发货。</p><p>适配层的意义不是「容忍后端乱改」，而是把变化收敛到一个明确的位置。页面结构保持不变，接口差异在边界上被消化。</p><h3 id="第二格-三层协议缓冲" tabindex="-1">第二格：三层协议缓冲 <a class="header-anchor" href="#第二格-三层协议缓冲" aria-label="Permalink to &quot;第二格：三层协议缓冲&quot;">​</a></h3><ul><li><strong>HTTP 层</strong>：<code>env.fetcher</code> 接收 amis 归一化的 <code>api</code> 配置，返回 <code>{ status: 200, data: 响应体 }</code>；</li><li><strong>业务层</strong>：<code>api.adaptor</code> 把响应体转成 <code>{ status: 0, msg, data }</code>；</li><li><strong>展示层</strong>：自定义 <code>Renderer</code> 把状态值转成徽章、颜色、文案。</li></ul><p>三层混在一起时，一个空白页面可能来自请求没发、响应没解析、字段没取到三种原因，排查成本极高。分开之后，每层都可以单独验证。</p><p>对应正文：<a href="./../guide/02-amis-advanced">env.fetcher 返回的是响应，不是业务数据</a>。</p><h3 id="第三格-联动与自定义组件" tabindex="-1">第三格：联动与自定义组件 <a class="header-anchor" href="#第三格-联动与自定义组件" aria-label="Permalink to &quot;第三格：联动与自定义组件&quot;">​</a></h3><p><code>visibleOn</code> 适合「状态决定哪个字段出现」，<code>disabledOn</code> 适合「状态决定哪个字段可编辑」。它们依赖当前数据域同步求值，不适合异步请求或复杂计算。</p><p>自定义组件的注册要早于渲染。<code>Renderer({ type: &quot;order-status&quot;, autoVar: true })</code> 让 Schema 里的 <code>${status}</code> 先求值再传入；组件内部还要对未知状态做兜底，避免后端新增枚举时白屏。</p><h3 id="第四格-改动收敛到一层" tabindex="-1">第四格：改动收敛到一层 <a class="header-anchor" href="#第四格-改动收敛到一层" aria-label="Permalink to &quot;第四格：改动收敛到一层&quot;">​</a></h3><p>验收时不要只看「页面能打开」，要验证三条链路：统计接口能适配、状态联动能生效、自定义徽章能渲染。三条都通过，才说明三层协议都工作正常。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>fetcher 直接返回业务数据</strong>：amis 取 <code>response.data</code> 得到 <code>undefined</code>，页面字段全空。</li><li><strong>adaptor 写在 <code>page</code> 上</strong>：它必须挂在 <code>api</code> 对象里，字符串形式的 <code>api</code> 没有位置挂。</li><li><strong>自定义组件只读 <code>props.status</code></strong>：表格列的数据在 <code>props.data.status</code>，要两种都兼容。</li><li><strong>注册晚于渲染</strong>：代码分割时尤其容易发生，表现为「未知组件」占位。</li><li><strong>表达式里写异步或可选链</strong>：公式引擎不支持，显隐会静默失效。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. `env.fetcher` 与 `api.adaptor` 的职责边界是什么？</b></summary><p>fetcher 负责 HTTP：发请求、处理鉴权与超时，返回 <code>{ status, data }</code> 形状的响应。adaptor 负责业务协议：把响应体转换成 amis 的 <code>{ status: 0, msg, data }</code>。前者可以全局复用，后者与页面语义相关，通常写在 Schema 里。</p></details><details><summary><b>2. 为什么自定义组件要同时读 `props.status` 和 `props.data.status`？</b></summary><p>同一个组件可能出现在两种场景：Schema 里写死 <code>status</code> 字面量，或者作为表格列读取当前行数据。前者走 <code>props.status</code>，后者走 <code>props.data.status</code>。两种都兼容，组件才能在面板、表格、表单里复用。</p></details><details><summary><b>3. 什么样的逻辑不该写进表达式？</b></summary><p>需要异步、需要访问外部状态、需要单测、或超过三行的逻辑都不该写进表达式。表达式只适合显隐、禁用、简单文案与四则运算。复杂规则应该下沉到自定义组件或独立的状态层，否则会变成难读难测的长字符串。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/02-amis-advanced">第 02 章正文</a></li><li><a href="./../guide/03-amis-editor">第 03 章 · amis 编辑器</a></li><li><a href="./../appendix/pitfalls">全站坑点索引</a></li></ul>',26)])])}const g=o(s,[["render",c]]);export{f as __pageData,g as default};
